#!/usr/bin/env bash
# @@REPO@@ — per-repo validation gate (stack: @@STACK@@).
# Generated by tools/validate/generate.sh. Edit freely afterwards; the generator
# will not overwrite this file without --force.
#
#   quick   seconds. Manifest parse + clippy/rustfmt.
#   full    minutes. The repo's own full gate.
set -uo pipefail
# shellcheck source=lib/validate-lib.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/validate-lib.sh"

TIER="$(tier_or_die "${1:-quick}")"

# --- quick -----------------------------------------------------------------

assert "workspace manifest present" 'test -f Cargo.toml'
assert "lockfile committed" \
  'test -f Cargo.lock || { echo "Cargo.lock missing — offline/vendored builds need it"; exit 1; }'

check "clippy -D warnings + rustfmt --check" "cargo" 'make lint'

[ "$TIER" = "quick" ] && { report "$TIER"; exit $?; }

# --- full ------------------------------------------------------------------

check "full gate (build && test && lint)" "cargo" 'make check'

report "$TIER"
